import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    const exitTimer = setTimeout(() => setIsExiting(true), 3200);
    const completeTimer = setTimeout(onComplete, 4000);
    return () => { 
      clearTimeout(exitTimer); 
      clearTimeout(completeTimer); 
    };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#000000] flex items-center justify-center relative overflow-hidden font-sans">

      {/* 1. THE AMBIENT "PULSE" (Swiggy/Apple Depth) */}
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="w-[100vw] h-[1px] bg-gradient-to-r from-transparent via-[#CAD23C] to-transparent opacity-20 animate-slice" />
      </div>

      {/* 2. THE LOGO ENGINE */}
      <div className={isExiting ? "animate-vacuum" : ""}>
        <div className="flex items-center justify-center relative">

          {/* T1 - The "Steel" Slide */}
          <motion.h1 
            initial={{ opacity: 0, x: -50, filter: "blur(10px)" }}
            animate={{ opacity: 1, x: 0, filter: "blur(0px)" }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
            className="text-[12rem] md:text-[18rem] font-[1000] italic text-[#FDFAD8] tracking-tighter leading-none"
          >
            T
          </motion.h1>

          {/* THE 2 - The "Electric" Core */}
          <motion.div 
            initial={{ scale: 0, rotate: 90, opacity: 0 }}
            animate={{ scale: 1, rotate: 0, opacity: 1 }}
            transition={{ type: "spring", stiffness: 300, damping: 15, delay: 0.4 }}
            className="relative mx-[-20px] z-10"
          >
            {/* High-End Glow Background */}
            <div className="absolute inset-0 bg-[#FF5B03] blur-[40px] opacity-40 animate-pulse" />

            <div className="bg-[#FF5B03] w-24 h-24 md:w-40 md:h-40 flex items-center justify-center border-t-[1px] border-l-[1px] border-white/40 shadow-[20px_20px_60px_rgba(0,0,0,0.8)] relative">
               <span className="text-white text-8xl md:text-[10rem] font-black italic select-none">2</span>
            </div>
          </motion.div>

          {/* T2 - The "Steel" Slide */}
          <motion.h1 
            initial={{ opacity: 0, x: 50, filter: "blur(10px)" }}
            animate={{ opacity: 1, x: 0, filter: "blur(0px)" }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1], delay: 0.2 }}
            className="text-[12rem] md:text-[18rem] font-[1000] italic text-[#FDFAD8] tracking-tighter leading-none"
          >
            T
          </motion.h1>
        </div>

        {/* 3. TACTICAL "WORKER" LINE */}
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 1 }}
          className="flex flex-col items-center mt-[-40px]"
        >
          <div className="flex items-center gap-4">
            <div className="w-12 h-[1px] bg-[#CAD23C]/50" />
            <span className="text-[#CAD23C] font-black text-2xl italic tracking-[0.4em] uppercase">
              Worker
            </span>
            <div className="w-12 h-[1px] bg-[#CAD23C]/50" />
          </div>

          {/* Minimal Bits readout */}
          <p className="mt-4 font-mono text-[8px] text-[#FDFAD8] opacity-20 tracking-[1em]">
            SYSTEM_INTEGRITY_CHECK: 100%
          </p>
        </motion.div>
      </div>

      {/* 4. THE "SCANLINE" (High-End Texture) */}
      <div className="absolute inset-0 pointer-events-none opacity-[0.03] bg-[linear-gradient(rgba(255,255,255,0)_50%,rgba(255,255,255,0.1)_50%)] bg-[length:100%_4px]" />
    </div>
  );
};

export default WorkerSplash;
